#include <stdio.h>
#include <stdlib.h>

#define INF 1000000000

static int N, K;
static int *head, *to, *nxt;
static int *parent, *order, *stack;
static int *maxD, *minD;
static int edgeCnt = 0;

static void addEdge(int u, int v) {
    to[edgeCnt] = v;
    nxt[edgeCnt] = head[u];
    head[u] = edgeCnt++;
}

static int feasible(int R) {
    for (int i = 1; i <= N; ++i) {
        maxD[i] = 0;
        minD[i] = INF;
    }

    int ans = 0;

    for (int idx = N; idx >= 1; --idx) {
        int u = order[idx];
        int m = maxD[u];
        int c = minD[u];

        if (c != INF && m >= 0 && m + c <= R) {
            m = -INF;
        }

        if (m == R) {
            ++ans;
            if (ans > K) return 0;
            m = -INF;
            c = 0;
        }

        maxD[u] = m;
        minD[u] = c;

        int p = parent[u];
        if (p != 0) {
            if (m >= 0) {
                int val = m + 1;
                if (val > maxD[p]) maxD[p] = val;
            }
            if (c < INF) {
                int val = c + 1;
                if (val < minD[p]) minD[p] = val;
            }
        }
    }

    if (maxD[1] >= 0) ++ans;
    return ans <= K;
}

int main(void) {
    scanf("%d %d", &N, &K);

    head = (int*)malloc((N + 1) * sizeof(int));
    to = (int*)malloc((2 * N) * sizeof(int));
    nxt = (int*)malloc((2 * N) * sizeof(int));
    parent = (int*)malloc((N + 1) * sizeof(int));
    order = (int*)malloc((N + 1) * sizeof(int));
    stack = (int*)malloc((N + 1) * sizeof(int));
    maxD = (int*)malloc((N + 1) * sizeof(int));
    minD = (int*)malloc((N + 1) * sizeof(int));

    for (int i = 1; i <= N; ++i) head[i] = -1;

    for (int i = 0; i < N - 1; ++i) {
        int a, b;
        scanf("%d %d", &a, &b);
        addEdge(a, b);
        addEdge(b, a);
    }

    parent[1] = 0;
    int top = 0;
    stack[top++] = 1;
    int cnt = 0;

    while (top > 0) {
        int u = stack[--top];
        order[++cnt] = u;

        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (v != parent[u]) {
                parent[v] = u;
                stack[top++] = v;
            }
        }
    }

    int lo = 0, hi = N;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (feasible(mid)) hi = mid;
        else lo = mid + 1;
    }

    printf("%d\n", lo);
    return 0;
}
